files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  min-height: 100vh;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

.wrapper {
  width: 600px;
  border: 1px solid #000;
  padding: 45px;
  background-color: #fff;
}

.text {
  font-size: 5vw;
  margin: 20px 0;
}
